/* @lc app=leetcode id=2641 lang=kotlin */
class Solution { fun replaceValueInTree(root: TreeNode?): TreeNode? = generateSequence(listOfNotNull(root)) { l -> l.flatMap { listOfNotNull(it.left, it.right) }.takeIf { it.isNotEmpty() } }.map { it.sumOf { n -> n.`val`.toLong() } }.toList().let { sums -> listOfNotNull(root).also { it.first().`val` = 0 }.let { java.util.ArrayDeque<Pair<TreeNode, Int>>().also { q -> q.add(root!! to 0) }.let { q -> generateSequence { q.poll() }.forEach { (n, d) -> ((if (n.left != null) n.left!!.`val` else 0) + (if (n.right != null) n.right!!.`val` else 0)).let { s -> n.left?.also { it.`val` = (sums[d + 1] - s).toInt().also { q.add(n.left!! to d + 1) } }.run { n.right?.also { it.`val` = (sums[d + 1] - s).toInt().also { q.add(n.right!! to d + 1) } } } } }.run { root } } } }